('test-fixture-commission-statement', 'eu-politics', 'article', 'published', 'TEST FIXTURE: Commission statement used to check the article layout locally', 'TEST FIXTURE ONLY. This local-only record checks the article template, key points, ad slots and source box. It never reaches the live database or site.', 'TEST FIXTURE ONLY: a local record used to check the article template before real stories exist.', '["Test fixture key point one.","Test fixture key point two.","Test fixture key point three."]', '["Test fixture paragraph one. It exists only in the local development database.","Test fixture paragraph two, used to check line length and spacing in the article body.","Test fixture paragraph three, after which the mid-article ad slot appears.","Test fixture paragraph four, closing the body."]', 'European Commission — Press corner', 'European Commission', 'https://ec.europa.eu/commission/presscorner/home/en', 'Press corner (test link)', '2026-11-09T10:00:00Z', 'test', strftime('%Y-%m-%dT%H:%M:%SZ','now','-50 minutes'), strftime('%Y-%m-%dT%H:%M:%SZ','now','-20 minutes'), '[{"at":"2026-11-09T10:00:00Z","note":"Test fixture created."}]', 0),
('test-fixture-white-house-live', 'us-politics', 'liveblog', 'published', 'TEST FIXTURE: live-blog layout check with timestamped updates', 'TEST FIXTURE ONLY. This local-only record checks the live-blog template with key points and timestamped updates. It never reaches the live database or site.', 'TEST FIXTURE ONLY: a local live-blog record used to check timestamped updates.', '["Fixture key point A.","Fixture key point B."]', '["Fixture background paragraph one.","Fixture background paragraph two."]', 'The White House — News', 'The White House', 'https://www.whitehouse.gov/news/', 'News (test link)', '2026-11-09T09:00:00Z', 'test', strftime('%Y-%m-%dT%H:%M:%SZ','now','-3 hours'), strftime('%Y-%m-%dT%H:%M:%SZ','now','-5 minutes'), '[]', 1),
('test-fixture-world-brief', 'world', 'article', 'published', 'TEST FIXTURE: third record so rails and related stories render', 'TEST FIXTURE ONLY. This local-only record fills the world rail and related stories so the layout can be checked. It never reaches the live database or the site.', 'TEST FIXTURE ONLY: fills the world rail.', '["Fixture point."]', '["Fixture paragraph.","Fixture paragraph two."]', 'European Commission — Press corner', 'European Commission', 'https://ec.europa.eu/commission/presscorner/home/en', 'Press corner (test link)', NULL, 'test', strftime('%Y-%m-%dT%H:%M:%SZ','now','-2 days'), strftime('%Y-%m-%dT%H:%M:%SZ','now','-2 days'), '[]', 0);
